/**
 * @method
 * @name bitopro#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/public/get_currency_info.md
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an associative dictionary of currencies
 */
func (this *Bitopro) FetchCurrenciesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Bitopro) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.PublicGetProvisioningCurrencies(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	//
	//     {
	//         "data":[
	//             {
	//                 "currency":"eth",
	//                 "withdrawFee":"0.007",
	//                 "minWithdraw":"0.001",
	//                 "maxWithdraw":"1000",
	//                 "maxDailyWithdraw":"2000",
	//                 "withdraw":true,
	//                 "deposit":true,
	//                 "depositConfirmation":"12"
	//             }
	//         ]
	//     }
	//
	var currencies []any = SafeListTypedDefault(response, "data", []any{})

	ch <- AsyncResult[map[string]any]{Value: this.ParseCurrencies(currencies)}
	return nil
}
func (this *Bitopro) ParseCurrency(rawCurrency any) map[string]any {
	var fiatCurrencies any = this.HandleOption("fetchCurrencies", "fiatCurrencies", []any{})
	var currencyId *string = this.SafeString(rawCurrency, "currency")
	var code *string = this.SafeCurrencyCode(currencyId)
	var deposit *bool = this.SafeBool(rawCurrency, "deposit")
	var withdraw *bool = this.SafeBool(rawCurrency, "withdraw")
	var isFiat bool = this.InArray(code, fiatCurrencies)
	return this.SafeCurrencyStructure(map[string]any{
		"id":   currencyId,
		"code": code,
		"info": rawCurrency,
		"type": func() string {
			if isFiat {
				return "fiat"
			}
			return "crypto"
		}(),
		"name":      nil,
		"active":    ((deposit != nil && *deposit == true) && (withdraw != nil && *withdraw == true)),
		"deposit":   deposit,
		"withdraw":  withdraw,
		"fee":       this.SafeNumber(rawCurrency, "withdrawFee"),
		"precision": nil,
		"limits": map[string]any{
			"withdraw": map[string]any{
				"min": this.SafeNumber(rawCurrency, "minWithdraw"),
				"max": this.SafeNumber(rawCurrency, "maxWithdraw"),
			},
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"networks": nil,
	})
}

