func (this *Bitopro) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// fetchTrades
	//         {
	//                 "timestamp":1644651458,
	//                 "price":"1180785.00000000",
	//                 "amount":"0.00020000",
	//                 "isBuyer":false
	//         }
	//
	// fetchMyTrades
	//         {
	//                 "tradeId":"5685030251",
	//                 "orderId":"9669168142",
	//                 "price":"11821.8",
	//                 "action":"SELL",
	//                 "baseAmount":"0.01",
	//                 "quoteAmount":"118.218",
	//                 "fee":"0.236436",
	//                 "feeSymbol":"BNB",
	//                 "isTaker":true,
	//                 "timestamp":1644905714862,
	//                 "createdTimestamp":1644905714862
	//         }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(trade, "tradeId")
	var orderId *string = this.SafeString(trade, "orderId")
	var timestamp *int64 = nil
	if id == nil {
		timestamp = this.SafeTimestamp(trade, "timestamp")
	} else {
		timestamp = this.SafeInteger(trade, "timestamp")
	}
	var marketId *string = this.SafeString(trade, "pair")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var symbol *string = this.SafeString(marketResolved, "symbol")
	var price *string = this.SafeString(trade, "price")
	var typeVar *string = this.SafeStringLower(trade, "type")
	var side *string = this.SafeStringLower(trade, "action")
	if side == nil {
		var isBuyer *bool = this.SafeBool(trade, "isBuyer")
		if isBuyer != nil && *isBuyer == true {
			side = SafeStringPtr("buy")
		} else {
			side = SafeStringPtr("sell")
		}
	}
	var amount *string = this.SafeString(trade, "amount")
	if amount == nil {
		amount = this.SafeString(trade, "baseAmount")
	}
	var fee map[string]any = nil
	var feeAmount *string = this.SafeString(trade, "fee")
	var feeSymbol *string = this.SafeCurrencyCode(this.SafeString(trade, "feeSymbol"))
	if feeAmount != nil {
		fee = map[string]any{
			"cost":     feeAmount,
			"currency": feeSymbol,
			"rate":     nil,
		}
	}
	var isTaker *bool = this.SafeBool(trade, "isTaker")
	var takerOrMaker *string = nil
	if isTaker != nil {
		if isTaker != nil && *isTaker {
			takerOrMaker = SafeStringPtr("taker")
		} else {
			takerOrMaker = SafeStringPtr("maker")
		}
	}
	return this.SafeTrade(map[string]any{
		"id":           id,
		"info":         trade,
		"order":        orderId,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"takerOrMaker": takerOrMaker,
		"type":         typeVar,
		"side":         side,
		"price":        price,
		"amount":       amount,
		"cost":         nil,
		"fee":          fee,
	}, marketResolved)
}

