func (this *Bitopro) ParseOrder(order any, optionalArgs ...any) Order {
	//
	// createOrder
	//         {
	//             "orderId": "2220595581",
	//             "timestamp": "1644896744886",
	//             "action": "SELL",
	//             "amount": "0.01",
	//             "price": "15000",
	//             "timeInForce": "GTC"
	//         }
	//
	// fetchOrder
	//         {
	//             "id":"8777138788",
	//             "pair":"bnb_twd",
	//             "price":"16000",
	//             "avgExecutionPrice":"0",
	//             "action":"SELL",
	//             "type":"LIMIT",
	//             "timestamp":1644899002598,
	//             "status":4,
	//             "originalAmount":"0.01",
	//             "remainingAmount":"0.01",
	//             "executedAmount":"0",
	//             "fee":"0",
	//             "feeSymbol":"twd",
	//             "bitoFee":"0",
	//             "total":"0",
	//             "seq":"BNBTWD548774666",
	//             "timeInForce":"GTC",
	//             "createdTimestamp":1644898944074,
	//             "updatedTimestamp":1644899002598
	//         }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString2(order, "id", "orderId")
	var timestamp *int64 = this.SafeInteger2(order, "timestamp", "createdTimestamp")
	var side *string = this.SafeString(order, "action")
	if side == nil {
		panic(ExchangeError(this.Id + " parseOrder() returned no side"))
	}
	side = SafeStringPtr(strings.ToLower(*side))
	var amount *string = this.SafeString2(order, "amount", "originalAmount")
	var price *string = this.SafeString(order, "price")
	var marketId *string = this.SafeString(order, "pair")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, "_")
	var symbol *string = this.SafeString(marketResolved, "symbol")
	var orderStatus *string = this.SafeString(order, "status")
	var status any = this.ParseOrderStatus(orderStatus)
	var typeVar *string = this.SafeStringLower(order, "type")
	var average *string = this.SafeString(order, "avgExecutionPrice")
	var filled *string = this.SafeString(order, "executedAmount")
	var remaining *string = this.SafeString(order, "remainingAmount")
	var timeInForce *string = this.SafeString(order, "timeInForce")
	var postOnly any = nil
	if timeInForce != nil && *timeInForce == "POST_ONLY" {
		postOnly = true
	}
	var fee map[string]any = nil
	var feeAmount *string = this.SafeString(order, "fee")
	var feeSymbol *string = this.SafeCurrencyCode(this.SafeString(order, "feeSymbol"))
	if Precise.StringGt(feeAmount, "0") {
		fee = map[string]any{
			"currency": feeSymbol,
			"cost":     feeAmount,
		}
	}
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": this.SafeInteger(order, "updatedTimestamp"),
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        timeInForce,
		"postOnly":           postOnly,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"amount":             amount,
		"cost":               nil,
		"average":            average,
		"filled":             filled,
		"remaining":          remaining,
		"status":             status,
		"fee":                fee,
		"trades":             nil,
		"info":               order,
	}, marketResolved)
}

/**
 * @method
 * @name bitopro#createOrder
 * @description create a trade order
 * @see https://github.com/bitoex/bitopro-offical-api-docs/blob/master/api/v3/private/create_an_order.md
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {object} [params.triggerPrice] the price at which a trigger order is triggered at
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bitopro) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Bitopro) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"type":      typeVar,
		"pair":      market["id"],
		"action":    side,
		"amount":    this.AmountToPrecision(symbol, amount),
		"timestamp": this.Milliseconds(),
	}
	var orderType string = strings.ToUpper(typeVar)
	if orderType == "LIMIT" {
		request["price"] = this.PriceToPrecision(symbol, price)
	}
	if orderType == "STOP_LIMIT" {
		request["price"] = this.PriceToPrecision(symbol, price)
		var triggerPrice *string = this.SafeString2(params, "triggerPrice", "stopPrice")
		if triggerPrice == nil {
			panic(InvalidOrder(this.Id + " createOrder() requires a triggerPrice parameter for " + orderType + " orders"))
		} else {
			request["stopPrice"] = this.PriceToPrecision(symbol, triggerPrice)
		}
		var condition *string = this.SafeString(params, "condition")
		if condition == nil {
			panic(InvalidOrder(this.Id + " createOrder() requires a condition parameter for " + orderType + " orders"))
		} else {
			request["condition"] = condition
		}
	}
	var paramsOmitted map[string]any = func() map[string]any {
		if orderType == "STOP_LIMIT" {
			return this.OmitDict(params, []any{"triggerPrice", "stopPrice"})
		}
		return params
	}()
	var postOnly bool = this.IsPostOnly((orderType == "MARKET"), nil, paramsOmitted)
	if postOnly {
		request["timeInForce"] = "POST_ONLY"
	}

	r1 := <-this.PrivatePostOrdersPair(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//     {
	//         "orderId": "2220595581",
	//         "timestamp": "1644896744886",
	//         "action": "SELL",
	//         "amount": "0.01",
	//         "price": "15000",
	//         "timeInForce": "GTC"
	//     }
	//
	ch <- AsyncResult[Order]{Value: this.ParseOrder(response, market)}
	return nil
}

